UITankNameGroup=function(game,gameController){Phaser.Group.call(this,game,null);this.gameController=gameController;this.tankName=this.addChild(new Phaser.Text(game,0,0,'',{font:UIConstants.TANK_NAME_FONT_SIZE+"px TankTrouble",fill:"#fff",strokeThickness:UIConstants.TANK_NAME_STROKE_WIDTH}));this.tankName.anchor.setTo(0.5,0.0);this.playerId=null;this.timeAlive=0.0;this.fading=false;this.exists=false;this.visible=false;this.log=Log.create('UITankNameGroup');};UITankNameGroup.prototype=Object.create(Phaser.Group.prototype);UITankNameGroup.prototype.constructor=UITankNameGroup;UITankNameGroup.prototype.update=function(){if(!this.exists||this.game.physics.arcade.isPaused){return;}var tank=this.gameController.getTank(this.playerId);if(tank){this.x=UIUtils.mpx(tank.getX());this.y=UIUtils.mpx(tank.getY())+Constants.TANK.HEIGHT.px*0.7;var halfWorldWidth=this.tankName.width*this.tankName.worldScale.x*0.5;var worldPosition=this.parent.toGlobal(this.position);if(worldPosition.x-halfWorldWidth<UIConstants.TANK_NAME_MARGIN){this.x=this.parent.toLocal({x:UIConstants.TANK_NAME_MARGIN+halfWorldWidth,y:worldPosition.y}).x;}else if(worldPosition.x+halfWorldWidth>this.game.width-UIConstants.TANK_NAME_MARGIN){this.x=this.parent.toLocal({x:this.game.width-UIConstants.TANK_NAME_MARGIN-halfWorldWidth,y:worldPosition.y}).x;}this.timeAlive+=this.game.time.delta/1000;if(!this.fading&&this.timeAlive>UIConstants.TANK_NAME_DISPLAY_TIME){this.fading=true;}}else{this.fading=true;}if(this.fading){this.alpha=Math.max(0.0,this.alpha-0.025);}if(this.alpha==0.0){this.exists=false;this.visible=false;}};UITankNameGroup.prototype.postUpdate=function(){if(!this.exists){return;}Phaser.Group.prototype.postUpdate.call(this);};UITankNameGroup.prototype.spawn=function(playerId){var tank=this.gameController.getTank(playerId);if(tank){this.x=UIUtils.mpx(tank.getX());this.y=UIUtils.mpx(tank.getY())+Constants.TANK.HEIGHT.px*0.7;this.exists=true;this.visible=true;this.alpha=1.0;this.tankName.setText("");}this.playerId=playerId;this.timeAlive=0.0;this.fading=false;var self=this;Backend.getInstance().getPlayerDetails(function(result){if(typeof(result)=="object"){var username=Utils.maskUnapprovedUsername(result);self.tankName.setText(username);}},function(result){},function(result){},this.playerId,Caches.getPlayerDetailsCache());};UITankNameGroup.prototype.retire=function(){this.exists=false;this.visible=false;};